ALTER TABLE learn_english_rpg_profiles ADD COLUMN IF NOT EXISTS daily_reward_date DATE NULL AFTER last_active_date;
ALTER TABLE learn_english_rpg_profiles ADD COLUMN IF NOT EXISTS review_correct INT UNSIGNED NOT NULL DEFAULT 0 AFTER class_energy;
ALTER TABLE learn_english_rpg_profiles ADD COLUMN IF NOT EXISTS speaking_correct INT UNSIGNED NOT NULL DEFAULT 0 AFTER review_correct;
CREATE TABLE IF NOT EXISTS learn_english_rpg_review_log(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,word VARCHAR(100) NOT NULL,is_correct TINYINT(1) NOT NULL,mode ENUM('choice','speaking') NOT NULL DEFAULT 'choice',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_rpg_review_user(user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO sys_page(code,module,title,route,description,is_active) VALUES('learn_english_rpg.reports','Pembelajaran','Analitik English RPG','learn-english-rpg/reports','Analitik progres, mastery, dan aktivitas English RPG',1) ON DUPLICATE KEY UPDATE title=VALUES(title),route=VALUES(route),is_active=1;
SET @grp=(SELECT id FROM sys_menu WHERE menu_key='learn.group' LIMIT 1);
INSERT INTO sys_menu(parent_id,page_id,menu_area,menu_key,title,icon,url,sort_order,is_visible,is_active,is_locked) VALUES(@grp,(SELECT id FROM sys_page WHERE code='learn_english_rpg.reports'),'MAIN','learn.english_rpg.reports','Analitik English RPG','ti ti-chart-bar','learn-english-rpg/reports',6,1,1,0) ON DUPLICATE KEY UPDATE parent_id=VALUES(parent_id),page_id=VALUES(page_id),is_active=1,is_visible=1;
INSERT INTO auth_role_permission(role_id,page_id,can_view,can_create,can_edit,can_delete,can_export,can_approve) SELECT r.id,p.id,1,0,0,0,1,0 FROM auth_role r CROSS JOIN sys_page p WHERE p.code='learn_english_rpg.reports' AND (r.id=2 OR UPPER(r.name) IN('ADMIN','SUPERADMIN')) ON DUPLICATE KEY UPDATE can_view=1,can_export=1;
